  private async move(tx:Tx,itemId:string,s:Snapshot,convert=false){const reservation=await tx.inventoryReservation.findFirstOrThrow({where:{orderItemId:itemId}});if(reservation.state!=='HELD')return;await tx.courseCohort.update({where:{id:s.cohortId},data:{reserved:{decrement:1},...(convert?{confirmed:{increment:1}}:{}),version:{increment:1}}});await tx.inventoryReservation.update({where:{id:reservation.id},data:{state:convert?'CONVERTED':'RELEASED',...(convert?{convertedAt:new Date()}:{releasedAt:new Date()}),version:{increment:1}}});}
